import{_ as e,o as s,c as a,a7 as i}from"./chunks/framework.DUCm5Bu5.js";const k=JSON.parse('{"title":"安裝","description":"準備工具鏈，從原始碼建置伺服器，或以 Docker 執行伺服器。","frontmatter":{"title":"安裝","description":"準備工具鏈，從原始碼建置伺服器，或以 Docker 執行伺服器。","updated":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"zh-tw/getting-started/installation.md","filePath":"zh-tw/getting-started/installation.md"}'),d={name:"zh-tw/getting-started/installation.md"};function o(l,t,n,h,p,r){return s(),a("div",null,[...t[0]||(t[0]=[i(`<p>Bubble Fighter Fantasy 是 Fantasy Tale Studio 維護的遊戲《泡泡大亂鬥》（Bubble Fighter）社群伺服器，以 C# 與 .NET 10 撰寫。伺服器能力由 YAML profile 中的模組列組合而成：profile 選擇某個用戶端版本需要的模組列，Host 負責啟用它們。本頁帶你從空白機器完成到確認可用的安裝：先決條件、目前已有的安裝方式、在 Windows 與 Linux 上從原始碼建置、執行 Docker Compose 組合、首次執行安裝助理，以及用來驗證每個步驟的檢查。</p><p><strong>本頁適合：</strong> 第一次部署伺服器、希望完成安裝並確認可執行的讀者。不需要事先了解本專案。</p><h2 id="安裝的是什麼" tabindex="-1">安裝的是什麼 <a class="header-anchor" href="#安裝的是什麼" aria-label="Permalink to &quot;安裝的是什麼&quot;">​</a></h2><p>你安裝的是伺服器 Host 以及它啟動時讀取的資料：</p><ul><li>Host 執行檔（<code>BubbleFighter.Fantasy.Host</code>）、模組組件，以及隨套件提供的 <code>profiles</code>、<code>packets</code>、<code>data</code> 與 <code>bootstrap</code> 目錄；</li><li>首次執行助理會在執行檔旁建立的安裝狀態目錄；</li><li>選用：你為要執行的用戶端版本自行準備的用戶端資料。</li></ul><p>儲存庫不包含遊戲用戶端，也不包含用戶端的專有資料。部分 profile 列需要相符版本的在本機檔案，缺少這些檔案時對應列會在啟用階段失敗。專案目前是預先發布版本（prerelease）：不同 profile 可用的玩法與所需資料不同，列出某個 profile 或通過自動檢查並不代表真實用戶端的相容性已經驗證。</p><p>每個版本都附有 Windows x64、Windows ARM64、Linux x64 與 Linux arm64 的預先編譯套件。在 Linux 上可以用安裝指令碼以原生方式或 Docker 方式安裝，見下文「安裝預先編譯套件」。原始碼建置與本儲存庫中的 Docker 檔案仍然可用。</p><h2 id="開始之前" tabindex="-1">開始之前 <a class="header-anchor" href="#開始之前" aria-label="Permalink to &quot;開始之前&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>用於</th><th>如何檢查</th></tr></thead><tbody><tr><td>Windows x64、Windows ARM64、Linux x64 或 Linux arm64</td><td>執行伺服器</td><td>系統設定；Linux 上執行 <code>uname -m</code></td></tr><tr><td>.NET 10 SDK</td><td>從原始碼建置</td><td><code>dotnet --version</code> 顯示 10.x</td></tr><tr><td>Node.js 20.19 或更新版本</td><td>從原始碼建置（建置時會編譯網頁介面）</td><td><code>node --version</code> 顯示 20.19 或更新</td></tr><tr><td>ASP.NET Core Runtime 10</td><td>執行相依於框架的建置輸出</td><td><code>dotnet --list-runtimes</code> 顯示 <code>Microsoft.AspNetCore.App 10.x</code></td></tr><tr><td>Git</td><td>從原始碼建置</td><td><code>git --version</code></td></tr><tr><td>Docker Engine 與 Compose</td><td>僅 Docker 方式</td><td><code>docker compose version</code></td></tr><tr><td>執行版本對應的用戶端資料</td><td>遊戲 profile</td><td><code>client-data/&lt;build&gt;/data</code> 存在</td></tr><tr><td>位於儲存庫根目錄的終端機</td><td>本頁除容器內部之外的每條命令</td><td><code>Get-Location</code> 或 <code>pwd</code></td></tr></tbody></table><p>儲存庫沒有規定最低 Windows 或 Linux 版本；請使用 .NET 10 SDK 支援的系統。選用的模組 SDK（Python、TypeScript、Go 與 Rust）在安裝或執行伺服器時都不需要。</p><h2 id="選擇安裝方式" tabindex="-1">選擇安裝方式 <a class="header-anchor" href="#選擇安裝方式" aria-label="Permalink to &quot;選擇安裝方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>狀態</th><th>適用情境</th></tr></thead><tbody><tr><td>Windows x64 建置套件</td><td>可用</td><td>Windows x64，希望使用現成建置</td></tr><tr><td>Windows ARM64 建置套件</td><td>可用</td><td>Windows on ARM，希望使用現成建置</td></tr><tr><td>Linux 安裝指令碼</td><td>可用</td><td>不使用 Docker 的 Linux 發行方式</td></tr><tr><td>Docker 一鍵安裝</td><td>可用</td><td>無需取出儲存庫，在容器中執行伺服器，可選附帶 MySQL</td></tr><tr><td>從本儲存庫建置 Docker</td><td>可用</td><td>已有取出與 Docker，在容器中執行伺服器與 MySQL</td></tr><tr><td>從原始碼建置</td><td>可用</td><td>希望在本機取得建置輸出與首次執行助理</td></tr></tbody></table><h2 id="安裝預先編譯套件" tabindex="-1">安裝預先編譯套件 <a class="header-anchor" href="#安裝預先編譯套件" aria-label="Permalink to &quot;安裝預先編譯套件&quot;">​</a></h2><p>每個版本附有四個套件與一份 <code>SHA256SUMS</code> 校驗清單。這些套件相依於框架：執行它們的電腦需要 ASP.NET Core Runtime 10。缺少執行階段時，Linux 安裝指令碼會自動安裝。</p><table tabindex="0"><thead><tr><th>套件</th><th>適用於</th></tr></thead><tbody><tr><td><code>bubblefighter-fantasy-win-x64.zip</code></td><td>Intel 或 AMD 64 位元處理器上的 Windows</td></tr><tr><td><code>bubblefighter-fantasy-win-arm64.zip</code></td><td>Windows on ARM</td></tr><tr><td><code>bubblefighter-fantasy-linux-x64.tar.gz</code></td><td>x86_64 上的 Linux</td></tr><tr><td><code>bubblefighter-fantasy-linux-arm64.tar.gz</code></td><td>aarch64 上的 Linux</td></tr></tbody></table><p>最新版本的檔案一律位於 <code>https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy/releases/latest/download/&lt;package&gt;</code>。</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>安裝符合處理器（x64 或 Arm64）的 <a href="https://dotnet.microsoft.com/download/dotnet/10.0" target="_blank" rel="noreferrer">ASP.NET Core Runtime 10</a>，或安裝已包含它的 .NET 10 SDK。</li><li>下載符合處理器的 ZIP，解壓縮到較短的資料夾，例如 <code>C:\\BubbleFighterFantasy</code>。完整路徑達到約 259 個字元的模組檔案無法在 Windows 上載入；從這麼深的資料夾啟動時，伺服器會拒絕啟動並指出最長的檔案。</li><li>按兩下 <code>BubbleFighter.Fantasy.Host.exe</code>。安裝助理隨即啟動，WebUI 會在預設瀏覽器中開啟；接著依照下文「首次執行設定」操作。關閉主控台視窗即停止伺服器。啟動失敗時視窗會保持開啟並顯示錯誤，按任意鍵後才關閉。</li></ol><h3 id="linux-安裝指令碼" tabindex="-1">Linux 安裝指令碼 <a class="header-anchor" href="#linux-安裝指令碼" aria-label="Permalink to &quot;Linux 安裝指令碼&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://wasabi-fantasytaledev.github.io/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>指令碼會辨識 x86_64 或 aarch64，從最新版本下載對應的套件與 <code>SHA256SUMS</code> 並校驗。系統沒有 ASP.NET Core Runtime 10 時，它會用 Microsoft 的 <code>dotnet-install.sh</code> 將執行階段安裝到安裝目錄中，不更動系統層級的 .NET。安裝目錄為 <code>~/bubblefighter-fantasy</code>，以 root 執行時為 <code>/opt/bubblefighter-fantasy</code>：</p><table tabindex="0"><thead><tr><th>路徑</th><th>內容</th></tr></thead><tbody><tr><td><code>releases/&lt;tag&gt;/</code></td><td>每個已安裝版本解壓縮後的套件</td></tr><tr><td><code>current</code></td><td>指向目前版本的連結</td></tr><tr><td><code>state/</code></td><td>安裝助理儲存的安裝狀態，升級時保留</td></tr><tr><td><code>dotnet/</code></td><td>執行階段，僅在安裝指令碼需要安裝時存在</td></tr><tr><td><code>bff</code></td><td>啟動器；不帶參數時啟動安裝助理</td></tr></tbody></table><p>用 <code>~/bubblefighter-fantasy/bff</code> 啟動伺服器，然後開啟 <code>http://127.0.0.1:8080/</code>。助理只監聽本機回送位址；在遠端伺服器上，請先在自己的電腦上用 <code>ssh -L 8080:127.0.0.1:8080 &lt;user&gt;@&lt;server&gt;</code> 轉送連接埠。</p><p>選項寫在 <code>bash -s --</code> 之後，例如 <code>curl -fsSL https://wasabi-fantasytaledev.github.io/install.sh | bash -s -- --service</code>：</p><table tabindex="0"><thead><tr><th>選項</th><th>作用</th></tr></thead><tbody><tr><td><code>--version &lt;tag&gt;</code></td><td>安裝指定版本而非最新版本</td></tr><tr><td><code>--dir &lt;path&gt;</code></td><td>安裝目錄</td></tr><tr><td><code>--admin-port &lt;n&gt;</code></td><td>安裝助理與 WebUI 的連接埠（預設 8080）</td></tr><tr><td><code>--service</code></td><td>以 root 執行時：建立並啟動 <code>bubblefighter-fantasy</code> systemd 服務，以 <code>bff</code> 系統使用者執行</td></tr><tr><td><code>--start</code></td><td>安裝完成後啟動伺服器</td></tr><tr><td><code>--no-runtime</code></td><td>缺少執行階段時直接失敗，而不是安裝它</td></tr><tr><td><code>--from &lt;dir&gt;</code></td><td>從存放版本檔案的目錄安裝，不下載</td></tr></tbody></table><p>升級時再次執行同一條命令即可。新版本會解壓縮到舊版本旁邊，並透過列出其 profile 進行檢查，檢查通過後才成為 <code>current</code>。<code>state/</code> 不會被更動。</p><h3 id="docker-一鍵安裝" tabindex="-1">Docker 一鍵安裝 <a class="header-anchor" href="#docker-一鍵安裝" aria-label="Permalink to &quot;Docker 一鍵安裝&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://wasabi-fantasytaledev.github.io/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --docker</span></span></code></pre></div><p>需要 Docker Engine 與 Compose 外掛。安裝指令碼會把 Linux 套件解壓縮到 <code>~/bubblefighter-fantasy/docker</code>，用它建置本機映像檔，並透過 Docker Compose 啟動伺服器容器。容器使用主機網路，因此你選擇的用戶端所用的遊戲連接埠都可以連線。預設不啟動資料庫容器：在安裝助理中選擇 SQLite（資料檔儲存在 <code>bff-state</code> 磁碟區中），或填寫既有的 MySQL 伺服器。</p><p>如需同時執行內建的 MySQL 8.4，請加上 <code>--with-mysql</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://wasabi-fantasytaledev.github.io/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --docker</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --with-mysql</span></span></code></pre></div><p>此時 MySQL 只監聽 <code>127.0.0.1:3306</code>（可用 <code>--mysql-port</code> 修改），產生的 <code>.env</code> 儲存隨機產生的資料庫密碼，只有其擁有者可以讀取。在安裝助理中選擇 MySQL，主機填 <code>127.0.0.1</code>，連接埠填安裝指令碼輸出的連接埠，資料庫 <code>bf_game_db</code>，使用者 <code>bff</code>，密碼為 <code>~/bubblefighter-fantasy/docker/.env</code> 中 <code>BFF_MYSQL_PASSWORD</code> 的值。</p><p>再次執行同一條命令即可升級；<code>.env</code> 與各個磁碟區都會保留，帶 MySQL 建立的部署升級後仍保留 MySQL。在該目錄中執行 <code>docker compose logs -f bff</code> 可以查看記錄。</p><h2 id="在-windows-上從原始碼建置" tabindex="-1">在 Windows 上從原始碼建置 <a class="header-anchor" href="#在-windows-上從原始碼建置" aria-label="Permalink to &quot;在 Windows 上從原始碼建置&quot;">​</a></h2><p>在 Windows PowerShell 中執行以下步驟。儲存庫可以複製到任意目錄；後續命令都在儲存庫根目錄執行。</p><h3 id="_1-複製儲存庫" tabindex="-1">1. 複製儲存庫 <a class="header-anchor" href="#_1-複製儲存庫" aria-label="Permalink to &quot;1. 複製儲存庫&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BubbleFighter.Fantasy</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd BubbleFighter.Fantasy</span></span></code></pre></div><p><code>&lt;repository-url&gt;</code> 是專案公布的儲存庫位址。如果你已經有取出或原始碼壓縮檔，請直接在該目錄開啟 PowerShell。</p><h3 id="_2-檢查-net-sdk" tabindex="-1">2. 檢查 .NET SDK <a class="header-anchor" href="#_2-檢查-net-sdk" aria-label="Permalink to &quot;2. 檢查 .NET SDK&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span></code></pre></div><p>命令必須輸出 10.x 版本。如果版本不符或找不到命令，請先安裝 .NET 10 SDK。</p><h3 id="build-all-projects-windows" tabindex="-1">3. 建置所有專案 <a class="header-anchor" href="#build-all-projects-windows" aria-label="Permalink to &quot;3. 建置所有專案 {#build-all-projects-windows}&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet build BubbleFighter.Fantasy.sln </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release</span></span></code></pre></div><p>首次建置會下載相依套件，可能需要幾分鐘。本儲存庫將警告視為錯誤，因此成功建置以下列輸出結束：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build succeeded.</span></span>
<span class="line"><span>    0 Warning(s)</span></span>
<span class="line"><span>    0 Error(s)</span></span></code></pre></div><h3 id="_4-找到建置輸出" tabindex="-1">4. 找到建置輸出 <a class="header-anchor" href="#_4-找到建置輸出" aria-label="Permalink to &quot;4. 找到建置輸出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>內容</th><th>位置</th></tr></thead><tbody><tr><td>Host 執行檔與程式庫</td><td><code>src/BubbleFighter.Fantasy.Host/bin/Release/net10.0/</code></td></tr><tr><td>模組建置輸出</td><td><code>artifacts/plugins/&lt;AssemblyName&gt;/</code></td></tr><tr><td>執行時使用的副本</td><td><code>&lt;host output&gt;/plugins/</code></td></tr><tr><td>Host 旁的隨附資料</td><td><code>&lt;host output&gt;/profiles/</code>、<code>packets/</code>、<code>data/</code>、<code>bootstrap/</code></td></tr></tbody></table><p>Host 建置會把模組目錄複製到 <code>&lt;host output&gt;/plugins/</code>，並在每次建置時取代該目錄，因此已刪除的模組不會殘留。複製到輸出中的 <code>profiles/</code> 不包含 <code>local.patch.yaml</code>；該檔案是被 Git 忽略的開發者覆寫檔案，只在取出的目錄中存在時才會生效。</p><h3 id="_5-執行建置好的-host" tabindex="-1">5. 執行建置好的 Host <a class="header-anchor" href="#_5-執行建置好的-host" aria-label="Permalink to &quot;5. 執行建置好的 Host&quot;">​</a></h3><p>在儲存庫根目錄執行，這樣預設的 <code>./profiles</code> 目錄才能解析：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\src\\BubbleFighter.Fantasy.Host\\bin\\Release\\net10.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BubbleFighter.Fantasy.Host.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiles list</span></span></code></pre></div><p>命令會為每個隨附的 profile 輸出一行，說明執行檔及其 profile 資料已就位。啟動安裝助理的隨附首次執行方式見下文「首次執行設定」。</p><p><strong>檢查是否成功：</strong> 建置以 <code>0 Warning(s)</code> 與 <code>0 Error(s)</code> 結束，且上面的命令輸出 profile 行而不是錯誤。</p><h2 id="在-linux-上從原始碼建置" tabindex="-1">在 Linux 上從原始碼建置 <a class="header-anchor" href="#在-linux-上從原始碼建置" aria-label="Permalink to &quot;在 Linux 上從原始碼建置&quot;">​</a></h2><p>在 POSIX shell 中執行以下步驟。儲存庫可以複製到任意目錄；後續命令都在儲存庫根目錄執行。</p><h3 id="_1-複製儲存庫-1" tabindex="-1">1. 複製儲存庫 <a class="header-anchor" href="#_1-複製儲存庫-1" aria-label="Permalink to &quot;1. 複製儲存庫&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">repository-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy</span></span></code></pre></div><h3 id="_2-檢查-net-sdk-1" tabindex="-1">2. 檢查 .NET SDK <a class="header-anchor" href="#_2-檢查-net-sdk-1" aria-label="Permalink to &quot;2. 檢查 .NET SDK&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>命令必須輸出 10.x 版本。</p><h3 id="build-all-projects-linux" tabindex="-1">3. 建置所有專案 <a class="header-anchor" href="#build-all-projects-linux" aria-label="Permalink to &quot;3. 建置所有專案 {#build-all-projects-linux}&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p>成功建置以 <code>Build succeeded.</code>、<code>0 Warning(s)</code> 與 <code>0 Error(s)</code> 結束。</p><h3 id="_4-執行建置好的-host" tabindex="-1">4. 執行建置好的 Host <a class="header-anchor" href="#_4-執行建置好的-host" aria-label="Permalink to &quot;4. 執行建置好的 Host&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/BubbleFighter.Fantasy.Host/bin/Release/net10.0/BubbleFighter.Fantasy.Host.dll</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profiles</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>請在儲存庫根目錄執行，這樣預設的 <code>./profiles</code> 目錄才能解析。DLL 旁的 apphost 執行檔用法相同。</p><h3 id="_5-注意執行階段需求" tabindex="-1">5. 注意執行階段需求 <a class="header-anchor" href="#_5-注意執行階段需求" aria-label="Permalink to &quot;5. 注意執行階段需求&quot;">​</a></h3><p>建置需要 .NET 10 SDK 與 Node.js 20.19 或更新版本：WebUi 專案會在首次建置時用 npm 編譯網頁介面，之後只在其原始碼變更時重新編譯。相依於框架的輸出（例如 <code>tools/publish-linux.ps1</code> 產生的發行目錄，或從容器映像複製出來的檔案）需要執行機器上安裝 ASP.NET Core Runtime 10。可用 <code>dotnet --list-runtimes</code> 檢查，確認存在 <code>Microsoft.AspNetCore.App 10.x</code>。下面的 Docker 方式會在映像內提供執行階段。</p><p><strong>檢查是否成功：</strong> 建置無警告無錯誤，且 <code>profiles list</code> 輸出 profile 行。</p><h2 id="使用本儲存庫的-docker-執行" tabindex="-1">使用本儲存庫的 Docker 執行 <a class="header-anchor" href="#使用本儲存庫的-docker-執行" aria-label="Permalink to &quot;使用本儲存庫的 Docker 執行&quot;">​</a></h2><p>在儲存庫根目錄、已安裝 Docker Engine 與 Compose 模組的前提下執行以下步驟。</p><h3 id="_1-建立環境變數檔案" tabindex="-1">1. 建立環境變數檔案 <a class="header-anchor" href="#_1-建立環境變數檔案" aria-label="Permalink to &quot;1. 建立環境變數檔案&quot;">​</a></h3><p>PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .env.example .env</span></span></code></pre></div><p>Linux shell：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>啟動前把 <code>.env</code> 中的 <code>BFF_MYSQL_PASSWORD</code> 設為非空的臨時值。Compose 會用它設定 MySQL 容器；<code>.env</code> 被 Git 忽略，絕不要提交。MySQL 連線變數在 <code>.env.example</code> 中有說明。</p><h3 id="_2-啟動伺服器與資料庫" tabindex="-1">2. 啟動伺服器與資料庫 <a class="header-anchor" href="#_2-啟動伺服器與資料庫" aria-label="Permalink to &quot;2. 啟動伺服器與資料庫&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/compose.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>compose 檔案會啟動兩個服務：</p><ul><li><code>bff</code> 使用 <code>deploy/docker/Dockerfile</code> 建置，建置內容為儲存庫根目錄。Dockerfile 先發布不含執行階段的 Host，再於 ASP.NET Core Runtime 10 映像中以非 root 系統使用者執行，進入點命令為 <code>dotnet BubbleFighter.Fantasy.Host.dll run --profile kr-1256</code>。映像宣告連接埠 7100、7101 與 8080。</li><li><code>mysql</code> 使用 <code>mysql:8.4</code> 映像，資料庫名稱為 <code>bf_game_db</code>、使用者為 <code>bff</code>、字元集為 utf8mb4，資料存放在 <code>mysql-data</code> 磁碟區中，並在伺服器啟動前通過健康檢查。</li></ul><p>對外發布的連接埠為伺服器的 7100、7101、8080，以及 MySQL 的 <code>\${BFF_MYSQL_PORT:-3306}</code>。伺服器把 <code>\${BFF_CLIENT_DATA_HOST:-../../client-data}</code>（即儲存庫中的 <code>client-data</code> 目錄）以唯讀方式掛載到 <code>/app/client-data</code>；容器需要 <code>client-data/kr-1256/data</code> 或 <code>client-data/kr-1256/dataraw</code>，否則 clientdata 列會失敗。兩個服務都使用 <code>restart: unless-stopped</code>。</p><p>容器方式會刻意啟動 MySQL，它不是隔離的本機檢查，也不使用本機檢查修補檔。管理監聽在容器內綁定 <code>127.0.0.1:8080</code>，如需透過發布的 8080 連接埠存取 WebUI，請在 <code>.env</code> 中加入 <code>BFF_ADMIN_HOST=0.0.0.0</code>。</p><h3 id="_3-追蹤記錄" tabindex="-1">3. 追蹤記錄 <a class="header-anchor" href="#_3-追蹤記錄" aria-label="Permalink to &quot;3. 追蹤記錄&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bff</span></span></code></pre></div><p>啟動記錄應與下文「首次執行設定」描述的行一致。按 Ctrl+C 只會停止記錄追蹤，<code>up</code> 啟動的服務仍在執行。</p><h3 id="_4-停止容器" tabindex="-1">4. 停止容器 <a class="header-anchor" href="#_4-停止容器" aria-label="Permalink to &quot;4. 停止容器&quot;">​</a></h3><p>在執行 compose 命令的終端機按 Ctrl+C，或在另一個終端機執行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span></code></pre></div><p><code>down</code> 會保留 <code>mysql-data</code> 磁碟區，之後再次 <code>up</code> 會繼續使用同一個資料庫。<code>docker compose -f deploy/docker/compose.yaml down -v</code> 會同時刪除該磁碟區及其中的全部遊戲資料，請只在資料可以捨棄時使用。</p><h3 id="手動單一容器方式" tabindex="-1">手動單一容器方式 <a class="header-anchor" href="#手動單一容器方式" aria-label="Permalink to &quot;手動單一容器方式&quot;">​</a></h3><p>如果不使用 compose 組合，而是自行執行一個容器，可以在儲存庫根目錄建置映像，並傳入可存取的 MySQL 與用戶端資料掛載：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bff-fantasy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BFF_MYSQL_HOST=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql-hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BFF_ADMIN_HOST=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7100:7100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7101:7101</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;client-data-directory&gt;:/app/client-data:ro&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bff-fantasy</span></span></code></pre></div><p>映像只複製發布後的 Host 與 <code>profiles</code> 目錄，不包含資料庫，也不包含用戶端資料。請把 <code>BFF_MYSQL_HOST</code> 指向容器能夠存取的位址。</p><p><strong>檢查是否成功：</strong> <code>docker compose -f deploy/docker/compose.yaml ps</code> 顯示各服務正在執行，伺服器記錄出現下一節所述的啟動行。首次建置可能需要幾分鐘。</p><h2 id="首次執行設定" tabindex="-1">首次執行設定 <a class="header-anchor" href="#首次執行設定" aria-label="Permalink to &quot;首次執行設定&quot;">​</a></h2><p>隨附的首次執行體驗會啟動內建 <code>setup</code> profile：安裝助理與管理 WebUI，不監聽任何遊戲連接埠。它可以在沒有用戶端資料、也沒有資料庫的空白機器上啟動；套用前需要選擇並測試資料庫。</p><h3 id="_1-不帶參數啟動-host" tabindex="-1">1. 不帶參數啟動 Host <a class="header-anchor" href="#_1-不帶參數啟動-host" aria-label="Permalink to &quot;1. 不帶參數啟動 Host&quot;">​</a></h3><p>在 Windows 上，開啟建置輸出目錄中的終端機並執行執行檔：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BubbleFighter.Fantasy.Host.exe</span></span></code></pre></div><p>請把隨附的 <code>profiles</code>、<code>packets</code> 與 <code>plugins</code> 目錄放在執行檔旁；建置輸出已經包含它們。處理程序會把工作目錄切換到執行檔所在目錄，因此從哪裡啟動都不影響。<code>start</code> 命令從不讀取儲存庫根目錄的 <code>.env</code>；助理把設定儲存在狀態目錄中。</p><p>狀態目錄預設是執行檔旁的 <code>state/</code>。<code>BFF_STATE_DIR</code> 或 <code>--state-dir &lt;directory&gt;</code> 可以覆寫它；相對路徑會依啟動處理程序時所在的目錄解析。</p><h3 id="_2-讀取列印的位址" tabindex="-1">2. 讀取列印的位址 <a class="header-anchor" href="#_2-讀取列印的位址" aria-label="Permalink to &quot;2. 讀取列印的位址&quot;">​</a></h3><p>主控台會列印管理監聽位址與 WebUI 位址：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Row &#39;admin.http&#39; admin API listening on 127.0.0.1:8080.</span></span>
<span class="line"><span>WebUI: http://127.0.0.1:8080/</span></span></code></pre></div><p>在瀏覽器開啟 <code>http://127.0.0.1:8080/</code>。管理監聽預設是 <code>127.0.0.1:8080</code>；如需修改，請在處理程序環境中設定 <code>BFF_ADMIN_HOST</code> 或 <code>BFF_ADMIN_PORT</code>（<code>start</code> 不讀取 <code>.env</code>）。</p><h3 id="_3-完成助理" tabindex="-1">3. 完成助理 <a class="header-anchor" href="#_3-完成助理" aria-label="Permalink to &quot;3. 完成助理&quot;">​</a></h3><ol><li>選擇介面語言：英文、簡體中文、繁體中文或韓文。</li><li>為伺服器命名（1 到 80 個字元）。</li><li>選擇一個或多個要啟用的用戶端版本。每個選取的版本有各自的用戶端資料選擇；你也可以暫時不提供資料，稍後在伺服器設定中匯入。</li><li>選用：現在匯入用戶端資料。選擇本機資料夾或準備好的 ZIP 套件，檢查篩選後的檔案數量與大小，然後按下「開始匯入」。瀏覽器本身的資料夾確認可能會統計資料夾內的全部檔案；助理會先把選擇篩選為用戶端封存檔與 <code>data</code>/<code>dataraw</code> 檔案，再顯示彙總。匯入會在狀態目錄中產生一份副本；失敗或取消的匯入只清理它自己的暫存檔案。</li><li>選擇資料庫。預設選取 MySQL：主機 <code>127.0.0.1</code>、連接埠 <code>3306</code>、資料庫 <code>bf_game_db</code>、使用者 <code>bff</code>。SQLite 預設把資料庫儲存在狀態目錄中。請執行「測試連線」；連線測試成功前助理不會繼續。</li><li>建立管理員帳號。使用者名稱 3 到 64 個字元，密碼至少 12 個字元。此帳號用於管理伺服器，隨安裝資訊一起儲存，與遊戲帳號分開。</li><li>檢查各項設定並套用。Host 會啟動所選 profile 的列；如果啟用失敗，會顯示可重試的錯誤碼。</li></ol><h3 id="_4-套用成功後磁碟上的內容" tabindex="-1">4. 套用成功後磁碟上的內容 <a class="header-anchor" href="#_4-套用成功後磁碟上的內容" aria-label="Permalink to &quot;4. 套用成功後磁碟上的內容&quot;">​</a></h3><p>在狀態目錄中會出現：</p><ul><li><code>installation.json</code>：儲存的設定與管理員憑證雜湊；</li><li><code>installation.lock</code>：防止兩個安裝程序同時管理同一狀態的鎖定檔案；</li><li><code>runtime.generated.patch.yaml</code>：衍生的持續性覆寫檔案（只有預留位置，不含資料庫憑證）；</li><li><code>administration/client-imports/&lt;token&gt;/</code>：每次匯入的用戶端資料副本各佔一個目錄；</li><li>選擇 SQLite 時的 <code>saves/fantasy.db</code>。</li></ul><h3 id="_5-匯入規則與限制" tabindex="-1">5. 匯入規則與限制 <a class="header-anchor" href="#_5-匯入規則與限制" aria-label="Permalink to &quot;5. 匯入規則與限制&quot;">​</a></h3><p>資料夾匯入接受用戶端原始相對路徑下的封存檔案（保留用戶端的字母大小寫），也接受路徑中包含 <code>data</code> 或 <code>dataraw</code> 的散裝檔案。ZIP 匯入接受一個標準單卷 ZIP，其項目為 <code>&lt;build&gt;/data</code> 或 <code>&lt;build&gt;/dataraw</code>，也可以位於最多兩層包裝目錄之下，例如 <code>client-data/&lt;build&gt;/data</code>。包含多個版本目錄的套件只匯入所選版本。不支援 ZIP64 與分卷壓縮檔；請先在本機解壓縮，再使用資料夾選擇。</p><p>也可選擇已安裝的遊戲資料夾：伺服器會自動產生所需資料，不需要 Python。只含伺服器資料的封存檔整包複製到 <code>data/</code>；混合封存檔中所需的小檔案解到 <code>dataraw/</code>，不擷取模型與材質。產生前會檢查必要檔案並回報缺少的檔名，成功後儲存到 <code>&lt;state-dir&gt;/client-data/&lt;build&gt;</code>。既有產生資料不會被覆寫；若需更換設定來源，請選擇預先整理好的資料。預先整理好的資料夾與 ZIP 仍作為獨立副本儲存到 <code>administration/client-imports/&lt;token&gt;/</code>。產生過程受上傳、解壓縮、儲存、檔案數與逾時限制。</p><p>匯入只是把檔案複製到安裝狀態；所需的資料表與封存檔內容會在遊戲服務啟動時檢查。匯入成功並不代表玩法或用戶端相容性已經驗證。</p><p>預設限制為每次上傳 8 GiB、每次匯入解壓資料 16 GiB、每次匯入 32,768 個檔案、保留 64 份副本、匯入儲存總量 64 GiB、每次匯入最長 20 分鐘。可在 <code>installation</code> 列中以 <code>client_data_upload_bytes</code>、<code>client_data_extracted_bytes</code>、<code>client_data_file_limit</code>、<code>client_data_copy_limit</code>、<code>client_data_storage_bytes</code> 與 <code>client_data_import_seconds</code> 調整。再次匯入不會刪除先前成功的副本。</p><p><strong>檢查是否成功：</strong> 助理報告安裝完成，WebUI 切換到管理介面。即使還沒有管理員，下文所述的 <code>/health</code> 檢查在助理執行期間也會正常回應。</p><h2 id="檢查安裝" tabindex="-1">檢查安裝 <a class="header-anchor" href="#檢查安裝" aria-label="Permalink to &quot;檢查安裝&quot;">​</a></h2><p>請在原始碼建置的儲存庫根目錄執行以下命令。它們檢查不同層面，建議三條都執行。</p><h3 id="_1-列出隨附的-profile" tabindex="-1">1. 列出隨附的 profile <a class="header-anchor" href="#_1-列出隨附的-profile" aria-label="Permalink to &quot;1. 列出隨附的 profile&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> profiles list</span></span></code></pre></div><p>命令會為每個隨附的 profile 輸出一行：id 與描述。本版本列出 19 個，其中包括 <code>setup</code>（“Database-independent first-run installation and administration.”）與 <code>management</code>（“Administration and durable storage only; no game or relay ports.”）。這證明 profile 檔案可以讀取並參與組合；它不能證明任何模組已經啟用。</p><h3 id="_2-列出找到的模組" tabindex="-1">2. 列出找到的模組 <a class="header-anchor" href="#_2-列出找到的模組" aria-label="Permalink to &quot;2. 列出找到的模組&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> plugins list</span></span></code></pre></div><p>命令會為每個找到的模組定義輸出一行：模組 id、版本、支援的用戶端版本以及載入來源。這證明 Host 旁的模組目錄可以被找到；它不能證明某個 profile 的列會啟用。</p><h3 id="_3-組合-profile-但不啟動" tabindex="-1">3. 組合 profile 但不啟動 <a class="header-anchor" href="#_3-組合-profile-但不啟動" aria-label="Permalink to &quot;3. 組合 profile 但不啟動&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BubbleFighter.Fantasy.Host </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">812</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patch tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">local</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">checks</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">isolated</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">memory.patch.yaml </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dump</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config</span></span></code></pre></div><p>這條命令要求已設定 <code>BFF_MYSQL_PASSWORD</code>，因為組合 MySQL 列時會插值 <code>\${BFF_MYSQL_PASSWORD}</code>，之後最後的修補檔才會停用該列。如果還沒有準備，請依<a href="./quickstart">快速入門</a>建立 <code>.env</code>。</p><p>命令以 YAML 輸出生效的列清單，每一列是一個以 <code>- id:</code> 開頭的區塊，然後以結束碼 0 結束。請確認以下內容：</p><ul><li><code>persistence.mysql</code> 列帶有 <code>disabled: true</code>；</li><li><code>persistence.memory</code> 列沒有 <code>disabled: true</code>，即已啟用；</li><li><code>clientdata</code> 列顯示 <code>kr-812</code> 解析後的 <code>data_directory</code> 與 <code>raw_directory</code>。</li></ul><p>此匯出證明組合、插值與修補檔順序：命令列修補檔最後套用，會覆寫開發者 <code>.env</code> 或本機修補檔中指向真實資料庫的設定。它不會啟動監聽，因此不能證明啟用或用戶端資料。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>當修補檔啟用 MySQL 時，設定匯出可能包含插值後的值，包括憑證。請把匯出視為敏感內容，不要貼到聊天或問題中。</p></div><h3 id="安裝助理路徑的瀏覽器檢查" tabindex="-1">安裝助理路徑的瀏覽器檢查 <a class="header-anchor" href="#安裝助理路徑的瀏覽器檢查" aria-label="Permalink to &quot;安裝助理路徑的瀏覽器檢查&quot;">​</a></h3><p>助理在預設位址執行時：</p><table tabindex="0"><thead><tr><th>檢查</th><th>命令</th><th>應看到的內容</th></tr></thead><tbody><tr><td>健康檢查</td><td><code>Invoke-RestMethod http://127.0.0.1:8080/health</code></td><td><code>status</code> = <code>ok</code> 以及 UTC 時間戳</td></tr><tr><td>安裝狀態</td><td><code>Invoke-RestMethod http://127.0.0.1:8080/api/setup/status</code></td><td>包含 <code>phase</code>、<code>installed</code>、<code>profiles</code> 與匯入限制的 JSON</td></tr></tbody></table><p>在 Linux 上使用 <code>curl -s http://127.0.0.1:8080/health</code> 與 <code>curl -s http://127.0.0.1:8080/api/setup/status</code>。<code>/health</code> 與 WebUI 檔案始終開放；在管理員尚未建立時，<code>/api/plugins</code> 依設計傳回 401，因此請先透過助理建立管理員。</p><p><strong>檢查是否成功：</strong> 三條原始碼建置命令都成功結束，瀏覽器檢查傳回上述 JSON。</p><h2 id="各部分的位置" tabindex="-1">各部分的位置 <a class="header-anchor" href="#各部分的位置" aria-label="Permalink to &quot;各部分的位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>內容</th><th>位置</th></tr></thead><tbody><tr><td>儲存庫取出</td><td>你複製到的目錄</td></tr><tr><td>Host 建置輸出</td><td><code>src/BubbleFighter.Fantasy.Host/bin/Release/net10.0/</code></td></tr><tr><td>模組建置輸出</td><td><code>artifacts/plugins/&lt;AssemblyName&gt;/</code>（被 Git 忽略）</td></tr><tr><td>Host 旁的檔案</td><td><code>&lt;host output&gt;/profiles/</code>、<code>packets/</code>、<code>data/</code>、<code>bootstrap/</code>、<code>plugins/</code></td></tr><tr><td>安裝狀態</td><td>執行檔旁的 <code>state/</code>；<code>BFF_STATE_DIR</code> 或 <code>--state-dir</code> 可覆寫</td></tr><tr><td>環境變數檔案</td><td>儲存庫根目錄的 <code>.env</code>；被 Git 忽略；<code>start</code> 不讀取</td></tr><tr><td>記錄</td><td>主控台輸出；封包記錄寫入工作目錄下的 <code>logs/{date}/</code></td></tr><tr><td>用戶端資料</td><td><code>client-data/&lt;build&gt;/data</code> 或 <code>dataraw</code>；可用 <code>BFF_CLIENT_DATA</code> 覆寫</td></tr><tr><td>Docker 資料</td><td><code>mysql-data</code> 磁碟區；用戶端資料以唯讀方式掛載</td></tr></tbody></table><p>除 <code>start</code> 之外，每條命令都會先把儲存庫根目錄的 <code>.env</code> 套用到尚未設定的處理程序環境變數；已存在的環境變數優先，且值永遠不會寫入記錄。</p><h2 id="停止與刪除" tabindex="-1">停止與刪除 <a class="header-anchor" href="#停止與刪除" aria-label="Permalink to &quot;停止與刪除&quot;">​</a></h2><ul><li><strong>停止原始碼建置或助理：</strong> 在終端機按 Ctrl+C。主控台會列印 <code>Shutdown complete.</code>，隨後處理程序結束。</li><li><strong>停止 Docker：</strong> 在前台 compose 命令中按 Ctrl+C，或執行 <code>docker compose -f deploy/docker/compose.yaml down</code>。只有確實要刪除資料庫磁碟區時才加 <code>-v</code>。</li><li><strong>刪除安裝狀態：</strong> 會移除儲存的安裝設定、管理員帳號、匯入的用戶端資料副本以及預設 SQLite 資料庫。此操作無法復原，請先停止伺服器。</li><li><strong>刪除資料庫：</strong> 會移除長期儲存的遊戲資料。請先備份，絕不要刪除玩家正在使用的線上資料庫。<a href="./../guides/deployment">部署</a>頁面說明了備份與升級。</li><li><strong>刪除建置輸出：</strong> 安全，重新執行建置命令即可恢復。</li></ul><h2 id="發生問題時" tabindex="-1">發生問題時 <a class="header-anchor" href="#發生問題時" aria-label="Permalink to &quot;發生問題時&quot;">​</a></h2><ul><li><strong>建置失敗：</strong> 本儲存庫將警告視為錯誤。第一條 <code>error</code> 會指出專案與原因，修正後重新建置。參見<a href="./../guides/troubleshooting">疑難排解</a>。</li><li><strong>相依於框架的建置無法啟動：</strong> 缺少 ASP.NET Core Runtime 10。用 <code>dotnet --list-runtimes</code> 確認，然後安裝相同架構的執行階段。</li><li><strong>連接埠已被占用：</strong> 助理使用 8080 連接埠，遊戲 profile 使用自己的遊戲連接埠，例如 <code>kr-812</code> 的 7110。請在 <code>.env</code> 中設定 <code>BFF_ADMIN_PORT</code> 或該版本的連接埠變數，或停止占用連接埠的處理程序。</li><li><strong>遊戲 profile 因用戶端資料失敗：</strong> <code>clientdata</code> 列會報告 <code>data_directory</code> 與 <code>raw_directory</code> 都不存在。請提供相符的用戶端資料，或透過安裝助理匯入，然後重新啟動該 profile。參見<a href="./../guides/troubleshooting">疑難排解</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>繼續閱讀<a href="./quickstart">快速入門</a>，啟動一個隔離的本機伺服器並確認它正在執行；然後閱讀<a href="./../guides/configuration">伺服器設定</a>，選擇持續性方式、連接埠與 profile 調整。如果需要長期執行的服務、備份與升級，請繼續閱讀<a href="./../guides/deployment">部署</a>。用戶端資料始終需要單獨提供：本儲存庫不包含遊戲用戶端及其資料。配套的 Fantasy Tale Launcher 有獨立指南：<a href="./../guides/launcher">啟動器</a>。</p>`,146)])])}const g=e(d,[["render",o]]);export{k as __pageData,g as default};
